<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\TemplateAsset\Application\Usecase\List;

use Psr\EventDispatcher\EventDispatcherInterface;

use Throwable;

use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Service\Visibility\TemplateAssetVisibilityService;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\Gateway\TemplateAssetReadGateway;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\Gateway\TemplateAssetFilter;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\Gateway\TemplateAssetCursor;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\Gateway\TemplateAssetAttributesSlide;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TemplateAssetListUsecase
{
  use LoggerAwareTrait;
  use TracerAwareTrait;

  public function __construct(
    private readonly EventDispatcherInterface $dispatcher,    private readonly TemplateAssetVisibilityService $visibility,
    private readonly TemplateAssetReadGateway $reader
  ) {
  }

  public function allowList(): Allow
  {
    $this->logDebug("Check allow of list usecase for Template asset");
    $span = $this->startSpan("Check allow of list usecase for Template asset");
    try {
      $result = $this->dispatcher->dispatch(new TemplateAssetListAllowDecision(Allow::allowed('list', 'Allowed to list by default')));
      return $result->getAllow();
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function count(TemplateAssetFilter $filter): int
  {
    $this->logDebug("Run list usecase for Template asset");
    $span = $this->startSpan("Run list usecase for Template asset");
    try {
      $allow = $this->allowList();
      if (!$allow->allowed) {
        throw new UnauthorizedException($allow->reason ?? 'Not allowed to list Template asset');
      }
      return $this->visibility->countVisibles($filter);
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function list(TemplateAssetFilter $filter, ?TemplateAssetCursor $cursor = null): TemplateAssetAttributesSlide
  {
    $this->logDebug("Run list usecase for Template asset");
    $span = $this->startSpan("Run list usecase for Template asset");
    try {
      $allow = $this->allowList();
      if (!$allow->allowed) {
        throw new UnauthorizedException($allow->reason ?? 'Not allowed to list');
      }
      $slide = $this->visibility->listVisibles($filter, $cursor);
      return new TemplateAssetAttributesSlide($slide->nextCursor(), array_map( fn($item) => $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($item)), $slide->values() ));
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
}
